/* Transcribed from the four supplied blank workbook photos. No answer key supplied. */
const workbookData={"questions": [[1, "graft", 3, "解释为什么欧亚种类葡萄藤通常需要进行嫁接。", "Explain why vitis vinifera grape vines are generally grafted.", "roots", "chain", "回看根瘤蚜怎样损害根系、欧亚葡萄的抗性，以及抗性砧木如何使所需酿酒品种继续生长。按原因→影响→嫁接的结果写完整因果链。"], [1, "mediterranean", 6, "描述地中海气候。解释地中海气候对葡萄的生长有怎样的优势和挑战。", "Describe a Mediterranean climate. Explain the advantages and challenges of a Mediterranean climate for grape growing.", "climate", "text", "先描述夏季和冬季的温度、降雨特征，再把日照、成熟、真菌病害与缺水风险连接起来。避免只列优缺点而不说明原因。"], [1, "freeze", 4, "对于葡萄种植者来说，哪种天气灾害的危害最大：春季霜冻还是冬季冰冻？请给出你的理由。", "Which weather hazard has the most deleterious effect on the grape grower: spring frost or winter freeze? Gives reasons for your answer.", "needs", "text", "比较受损组织、当年产量、植株存活与恢复时间。结合冻害强度说明判断，区分当季新梢损伤和永久木质部分乃至整株死亡的长期后果。"], [1, "heat", 3, "描述天气过热和强烈的阳光对红葡萄酒最终风格的影响。", "Describe the effect of strong heat and sunlight on the final style of a red wine.", "needs", "text", "把葡萄糖分、酸度、风味的发展连接到酒精度、酸度与果味；注意题目中的“过热”，区分成熟促进与极端热害、缺水造成的成熟受阻。"], [2, "vsp", 5, "“新枝垂直分布形（VSP）”最适合什么样的气候？解释这样的架型如何提高葡萄的质量。", "What type of climate is VSP best suited to? Explain how VSP trellising can improve the quality of grapes.", "canopy", "text", "回看凉爽或温和条件下受光与通风的需求，解释新梢排列怎样改变遮阴、成熟和病害风险；炎热强光地区还需考虑果实遮护。"], [2, "bush", 4, "解释“灌木形/杯型（bush vine/goblet）”整形方式的优势和劣势。", "Explain the advantages and disadvantages of growing bush vines/goblet.", "training", "chain", "从树形、是否需要搭架、果实遮阴和机械作业条件出发，写明何种环境下成为优势或限制。不要把“便宜”或“品质好”作为无条件结论。"], [2, "harvest", 8, "你应该选择什么样的采收方式？为什么？", "What method of harvesting should you pick and why? (8 marks)", "harvest", "harvest", "逐行情境判断地形、规模、选择性与成本。山坡是否陡到限制机器需要说明；仅凭“Bordeaux AOP Rouge”不能推断唯一采收方式，也不能编造强制人工采收的法规。"], [2, "bordeaux", 3, "波尔多有着温和的海洋性气候。请列举出3个在葡萄生长过程中会遇到的问题（可以包含病害、虫害和天气灾害）。", "Bordeaux has a maritime climate. Please list 3 problems that may be encountered during the grape growing season (can include diseases, pest and weather hazards).", "health", "three", "列出三个不同且适合当地条件的问题，避免把同一病害换词重复计算。可回看潮湿相关的真菌病害及生长季天气风险。"]], "white": ["Chardonnay 霞多丽", "Riesling 雷司令", "Sauvignon Blanc 长相思", "Pinot Gris 灰皮诺", "Gewurztraminer 琼瑶浆", "Viognier 维欧尼", "Albariño 阿尔巴利诺", "Muscat/Moscato 麝香/莫斯卡托", "Chenin Blanc 白诗南", "Semillon 赛美蓉", "Furmint 福尔明", "Glera 格雷拉", "Cortese 柯蒂斯", "Garganega 卡尔卡耐卡", "Verdicchio 维蒂奇诺", "Fiano 菲亚诺"], "red": ["Zinfandel/Primitivo 金粉黛/普里米蒂沃", "Carménère 佳美娜", "Malbec 马尔贝克", "Pinotage 皮诺塔吉", "Gamay 佳美", "Montepulciano 蒙特普奇亚诺", "Barbera 巴贝拉", "Corvina 科维纳", "Sangiovese 桑娇维塞", "Nebbiolo 内比奥罗"]};
function workbookField(key,label,placeholder='用自己的话填写…'){
 const id='wb-'+key;return `<label class="wb-field" for="${id}"><span>${label}</span><textarea id="${id}" data-note="workbook-${key}" placeholder="${placeholder}">${safe(read(notesKey('workbook-'+key),''))}</textarea></label>`;
}
function workbookQuestion(q,i){const [session,id,marks,zh,en,unit,type,hint]=q;const key=`s${session}-${id}`;let fields='';
 if(type==='chain')fields=`<div class="wb-chain">${workbookField(key+'-a','因为有 A · Because of A',session===2?'灌木形/杯型整形方式的特点…':'原因…')}${workbookField(key+'-b','所以有 B 的影响 · Thus there is B','这一原因产生的影响…')}${workbookField(key+'-c','于是 C 的效果 · So it results in C',session===1?'欧亚种类葡萄藤通常需要嫁接…':'优势或劣势…')}</div>`;
 else if(type==='harvest')fields=['大批量的长相思 · Bulk Sauvignon Blanc','山坡的雷司令 · Hillside Riesling','贵腐葡萄 · Botrytis Grapes','波尔多干红 · Bordeaux AOP Rouge'].map((name,j)=>`<fieldset class="wb-harvest"><legend>${name}</legend><div class="wb-two">${workbookField(key+'-'+j+'-method','采摘方式 · Harvest Method')}${workbookField(key+'-'+j+'-reason','使用该采收方式的原因 · Reasons for harvest method')}</div></fieldset>`).join('');
 else if(type==='three')fields=[1,2,3].map(j=>workbookField(key+'-'+j,'问题 '+j)).join('');
 else fields=workbookField(key,'我的作答 · My answer','先作答，再展开复习提示。');
 return `<section class="quiz-card wb-question"><div class="eyebrow">QUESTION ${i+1} · ${marks} 分 / MARKS</div><h2>${zh}</h2><p class="wb-english" lang="en">${en}</p>${fields}<details class="recall"><summary>写完后再看 · 复习提示</summary><p>${hint}</p><p class="fine">小 P 根据已收录课程整理的提示，不是练习册参考答案或评分细则。</p><a href="${session===1?'#lesson/':'#session2/'}${unit}">回看对应阅读单元 ↗</a></details></section>`;
}
function workbookVarieties(kind){const white=kind==='white',names=workbookData[kind],labels=white?['甜度 · Sweetness','酸度 · Acidity','酒体 · Body','味道特征 · Flavour Characteristic']:['颜色深度 · Colour intensity','酸度 · Acidity','单宁 · Tannins','味道特征 · Flavour Characteristic'];return `<section class="wb-varieties"><h2>${white?'白葡萄品种':'红葡萄品种'} · ${names.length} 项</h2><p class="fine">Session 1 练习册第 ${white?'2':'3'} 页 · 按照片顺序保留全部品种和栏目。根据所学酒款或产区填写；同一品种的甜度、酒体等会随酿造方式与产区变化。</p><div class="wb-variety-grid">${names.map((name,i)=>`<fieldset class="wb-variety"><legend>${name}</legend>${labels.map((label,j)=>workbookField('s1-'+kind+'-'+i+'-'+j,label)).join('')}</fieldset>`).join('')}</div></section>`}
function workbookView(which){const session=which==='2'?2:1,qs=workbookData.questions.filter(q=>q[0]===session);return `<main id="main" class="wrap wb-page"><a class="back" href="${session===1?'#quiz':'#session2quiz'}">← Session ${session} 自测</a><div class="page-intro"><div class="eyebrow">WORKBOOK / SESSION ${session}</div><h1 class="page-title">把思路，写成答案。</h1><p>Session ${session} 练习册 · ${qs.length} 道简答题 · 共 ${qs.reduce((n,q)=>n+q[2],0)} 分${session===1?' · 另含26个品种填写表':''}</p><nav class="wb-tabs" aria-label="选择练习册"><a href="#workbook/1" ${session===1?'aria-current="page"':''}>Session 1 · 葡萄藤与环境</a><a href="#workbook/2" ${session===2?'aria-current="page"':''}>Session 2 · 葡萄园管理</a></nav></div><aside class="callout"><strong>保留原题，先独立作答。</strong><p>题干、分值及填写栏目来自这次提供的4张练习册照片。未收到参考答案，不自动评分；折叠提示由小 P 整理。Session 1 收录简答页及品种表第2、3页；Session 2 收录本次提供的简答页，不代表整本练习册已齐。</p><small id="note-status" role="status">输入后自动保存到当前浏览器，不跨设备同步。</small></aside>${qs.map(workbookQuestion).join('')}${session===1?workbookVarieties('white')+workbookVarieties('red'):''}<p class="fine">品种中英文沿用练习册；题目没有附带插图。纸本原页未公开上传。</p></main>`}
